// Кейс: .qa/tests/alerts/ALR-005.md (шаг 2) · план: .qa/e2e-app/specs/app.md (1.17)
// Только главный телефон: доставку на второй телефон Appium не видит — проверяется вручную (ALR-005 шаг 3).
// Побочный эффект: тестовое уведомление уходит на телефоны аккаунта (данные не меняются).
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab, waitEnabled } from '../../lib/banci.mjs';

export const name = '«חשבון» → «התרעות וצפצוף» → «שליחת התרעת בדיקה» нажимается без ошибки #48f2b9 @iphone @app';

const ERRORS = ['משהו השתבש', 'שגיאה', 'לא הצלחנו', 'נכשל'];

export default async function (app) {
  // 1. «חשבון» → «התרעות וצפצוף».
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('התרעות וצפצוף'), { what: 'строка «התרעות וצפצוף» в «חשבון»' });
  await row.click();

  // 2. Кнопка «שליחת התרעת בדיקה» есть и активна.
  const btn = await app.scrollTo(by.begins('שליחת התרעת בדיקה'), { what: 'кнопка «שליחת התרעת בדיקה»' });
  await waitEnabled(btn, true, { what: '«שליחת התרעת בדיקה»' });

  // 3. Нажать → отправка завершилась (кнопка снова активна), ошибок нет.
  await btn.click();
  const after = await app.waitFor(by.begins('שליחת התרעת בדיקה'), { what: '«שליחת התרעת בדיקה» после нажатия' });
  await waitEnabled(after, true, { timeout: 20000, what: '«שליחת התרעת בדיקה» после отправки' });
  for (const e of ERRORS) assert(!(await app.exists(by.contains(e))), `после «שליחת התרעת בדיקה» нет ошибки «${e}»`);

  await app.restart();
}
